contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newFee) public payable {
        // Attempt to set a fee that must be rejected by the contract itself.
        bool reverted;
        if (newFee >= 30) {
            try c.setFee(newFee) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            // Precondition-free accepted case: fee must be stored exactly.
            c.setFee(newFee);
            assert(c.fee() == newFee && newFee < 30);
        }
    }

    receive() external payable {}
}

