contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newFee) public payable {
        uint256 oldFee = c.fee();
        bool reverted;
        if (newFee >= 30) {
            // must revert as a top-level state-changing call cannot be wrapped; use try/catch on a top-level statement form instead
            try c.setFee(newFee) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.fee() == oldFee);
        } else {
            c.setFee(newFee);
            assert(c.fee() == newFee);
        }
    }
    receive() external payable {}
}

