        });

        bytes32 orderHash = c.hashOrder(order);
        require(!c.cancelledOrders(orderHash), "pre-state already cancelled");

        c.cancel(order);

        bool cancelledAfter = c.cancelledOrders(orderHash);

        // cancelling the same order hash for a differently-shaped order is impossible;
        // instead verify effect on fillOrder: it must revert because order was cancelled.
        bytes memory signature = new bytes(65);
        uint256[] memory floorAssetTokenIds = new uint256[](0);
