        // (using low-level call to capture revert without try block on state-changing call
        //  is not permitted either; so use try/catch which is a statement, not nested)
        // NOTE: try/catch counts as top-level statement usage of the call.
        //
        // To satisfy the "own top-level statement" constraint we use try/catch directly.
        //
        // Implementation:
        // (declared below)
        //
        // We already made c.cancel(order) a top-level statement above.

        try c.fillOrder(order, signature, floorAssetTokenIds) {
            fillReverted = false;
        } catch {
            fillReverted = true;
        }

        assert(cancelledAfter && fillReverted);
    }

